// Family shoes options, shared by the customer form, the save route, the admin view and the Drive folder.
// The option list itself is generated by scripts/build-shoes-catalog.cjs.
import raw from "./catalog.json";

export type ShoeOption = { id: string; file: string; code: string | number };
export type ShoeType = "Man" | "Woman" | "Child" | "Baby";
export type Pose = "crossed" | "open";
type PoseOptions = { legs: ShoeOption[]; shoes: ShoeOption[] };
type Catalog = {
  builtAt: string;
  maxPeople: number;
  skins: { code: string; hex: string }[];
  people: Record<ShoeType, { poses: Partial<Record<Pose, PoseOptions>> }>;
};

export const shoesCatalog = raw as Catalog;
export const SHOE_TYPES: ShoeType[] = ["Man", "Woman", "Child", "Baby"];
export const MAX_SHOE_PEOPLE = shoesCatalog.maxPeople;
export const shoeThumb = (o: { id: string }) => `/shoes/${o.id}.webp`;

/** Poses available for a person type (only children get a choice). */
export const posesFor = (t: ShoeType) => Object.keys(shoesCatalog.people[t].poses) as Pose[];

export type ShoeMember = { type: ShoeType; name?: string; skin?: string; pose?: Pose; shoe?: number };
export type ShoesSubmission = { title?: string; notes?: string; members: ShoeMember[] };

export function poseOf(m: ShoeMember): Pose {
  const poses = posesFor(m.type);
  return m.pose && poses.includes(m.pose) ? m.pose : poses[0];
}
const optionsFor = (m: ShoeMember) => shoesCatalog.people[m.type].poses[poseOf(m)]!;

export function shoeMissing(m: ShoeMember): string[] {
  const miss: string[] = [];
  if (!m.skin) miss.push("skin tone");
  if (posesFor(m.type).length > 1 && !m.pose) miss.push("legs crossed or open");
  if (!m.shoe) miss.push("shoes");
  return miss;
}

export function validShoeMember(m: ShoeMember): boolean {
  if (!SHOE_TYPES.includes(m.type)) return false;
  if (m.pose && !posesFor(m.type).includes(m.pose)) return false;
  if (m.skin && !shoesCatalog.skins.some((s) => s.code === m.skin)) return false;
  if (m.shoe && !optionsFor(m).shoes.some((o) => o.code === m.shoe)) return false;
  return shoeMissing(m).length === 0;
}

export const shoeChoices = (m: ShoeMember) => optionsFor(m).shoes;

export type ResolvedShoePart = { part: string; label: string; file: string; thumbId: string };
export type ResolvedShoeMember = { position: number; who: string; parts: ResolvedShoePart[] };

const TYPE_WORD: Record<ShoeType, string> = { Man: "Man", Woman: "Woman", Child: "Child", Baby: "Baby" };

/** Turn picks into exact Drive files. */
export function resolveShoes(sub: ShoesSubmission): ResolvedShoeMember[] {
  return sub.members.map((m, i) => {
    const o = optionsFor(m);
    const legs = o.legs.find((l) => l.code === m.skin) ?? o.legs[0];
    const shoe = o.shoes.find((s) => s.code === m.shoe);
    const poseNote = posesFor(m.type).length > 1 ? `, legs ${poseOf(m)}` : "";
    const name = m.name?.trim();
    const parts: ResolvedShoePart[] = [{ part: "Legs", label: `Skin ${legs.code}${poseNote}`, file: legs.file, thumbId: legs.id }];
    if (shoe) parts.push({ part: "Shoes", label: `Shoe ${shoe.code}`, file: shoe.file, thumbId: shoe.id });
    return { position: i + 1, who: `${TYPE_WORD[m.type]}${name ? ` (${name})` : ""}`, parts };
  });
}

/** Plain-text version for the log and the notification email. */
export function shoesText(sub: ShoesSubmission): string {
  const lines = resolveShoes(sub).map((r) => `${r.position}. ${r.who}: ${r.parts.map((p) => p.label).join(", ")}`);
  return [
    sub.title ? `Family name: ${sub.title}` : null,
    `People: ${sub.members.length}`,
    ...lines,
    sub.notes ? `Notes: ${sub.notes}` : null,
  ].filter(Boolean).join("\n");
}
